    $content='';$title=prime_pages_map()[$key][0];
    if(in_array($key,['lease','regular','carpet'],true)) {
        $service=['lease'=>'lease','regular'=>'regular','carpet'=>'carpet'][$key];$estimate=add_query_arg('prime_service',$service,prime_page_link('prices'));
        $content.=prime_section(prime_cols([prime_p('MELBOURNE '.strtoupper($title),'pp-eyebrow').prime_h(['lease'=>'End of Lease Cleaning','regular'=>'A cleaner home, on your schedule','carpet'=>'Freshen up your carpets'][$key],1).prime_p(prime_lorem()).prime_sc('[prime_starting_price service="'.$service.'"]').prime_buttons('Get '.($key==='lease'?'an end-of-lease':'a '.($key==='carpet'?'carpet':'house cleaning')).' estimate',$estimate).prime_p('Service preselected: '.esc_html($title),'pp-small'),prime_photo($key,['lease'=>'Illustrative empty living room with timber floor','regular'=>'Illustrative beige sofa with mint cushions','carpet'=>'Illustrative carpet extraction wand'][$key],true)],'pp-hero'));
