            $content.=prime_section(prime_h('Choose a cleaning frequency',2,'pp-centre').prime_cols($cards).prime_sc('[prime_discount_message]').prime_g(prime_cols([prime_h('Need a deeper clean?',3).prime_p('Choose Deep / Spring in the estimator for a more detailed clean.'),prime_buttons('Explore Deep / Spring',add_query_arg('prime_service','deep',prime_page_link('prices')))]),'pp-callout'));
