        $content.=prime_faq(['What is included?'=>'The detailed checklist is awaiting client approval. Please tell us about any specific requirements.',$key==='lease'?'Is the property furnished?':'Can I request extra cleaning?'=>$key==='lease'?'Furnished End of Lease properties follow the custom-quote path.':'Select the relevant add-ons in the estimator. Missing approved rates are handled through a custom quote.','How is the estimate calculated?'=>'The estimator uses your service, property, extras and approved suburb. You see an indicative range before providing contact details.']).prime_cta();
        if($key==='lease')$content.=prime_section(prime_g(prime_p('<strong>Your agent makes the bond decision.</strong> We do not guarantee bond return.'),'pp-callout'));
    } elseif($key==='prices') {
        $content.=prime_section(prime_cols([prime_p('YOUR CLEAN, CLEARLY PRICED','pp-eyebrow').prime_h('Your cleaning estimate, step by step',1).prime_p('See an indicative range before sharing your details.').prime_p('Tell us about your service and property. Your estimate is a guide, not a confirmed price or booking.').prime_p('Quick and easy · Personalised range','pp-small'),prime_photo('regular','Illustrative home interior',true)],'pp-hero'),'pp-compact-hero');
        $content.=prime_section(prime_sc('[prime_cleaning_estimator]'),'pp-estimator-section');
        $content.=prime_section(prime_h('A simple way to get started',2,'pp-centre').prime_cols([prime_g(prime_p('01','pp-eyebrow').prime_h('Tell us what you need',3).prime_p('Choose your service, property and extras.'),'pp-card'),prime_g(prime_p('02','pp-eyebrow').prime_h('See your estimate',3).prime_p('Review the indicative range and price breakdown.'),'pp-card'),prime_g(prime_p('03','pp-eyebrow').prime_h('Send your enquiry',3).prime_p('We will follow up to confirm your requirements.'),'pp-card')]),'pp-mint');
        $content.=prime_section(prime_cols([prime_h('How pricing works').prime_p('Your service, property and selected extras inform the range. Missing rates always lead to a custom quote.').prime_p('The final scope and price are confirmed personally before work begins.'),prime_photo('lease','Illustrative home interior')]),'pp-pricing-explainer');
        $content.=prime_faq(['How does pricing work?'=>'Separate End of Lease and Regular grids apply. Deep / Spring uses the editable multiplier. Your selected extras and approved travel zone are included in the breakdown.','When do I need a custom quote?'=>'6+ bedrooms, 5+ bathrooms, furnished End of Lease, unlisted suburbs or an unavailable applicable price require a custom quote.','Is this a confirmed booking?'=>'No. Preferred dates and times are requests. Payment is due on completion.']).prime_cta();
    } elseif($key==='about') {
        $content.=prime_section(prime_cols([prime_p('ABOUT PRIME','pp-eyebrow').prime_h('Local care. A fresh approach.',1).prime_p(prime_lorem()).prime_buttons('Get an estimate',prime_page_link('prices')).prime_buttons('Contact us',prime_page_link('contact'),true),prime_g(prime_photo('regular','Illustrative living room',true).prime_photo('carpet','Illustrative carpet cleaning'),'pp-photo-collage')],'pp-hero'));
        $content.=prime_section(prime_h('Our approach').prime_p('A simple, clear approach to caring for your home.').prime_cols([prime_g(prime_icon_block('home').prime_h('Your home',3).prime_p(prime_lorem()),'pp-card'),prime_g(prime_icon_block('calculator').prime_h('Clear estimates',3).prime_p(prime_lorem()),'pp-card'),prime_g(prime_icon_block('calendar').prime_h('Simple enquiries',3).prime_p(prime_lorem()),'pp-card')]));
        $content.=prime_section(prime_h('Business information').prime_p('Meet Prime Domestic & Cleaning Services in Melbourne.').prime_cols([prime_g(prime_icon_block('home').prime_h('Business story',3).prime_p('Business history and team content awaiting client approval.'),'pp-card'),prime_g(prime_icon_block('shield').prime_h('Credentials',3).prime_p('Verified credentials awaiting client approval.'),'pp-card'),prime_g(prime_icon_block('office').prime_h('Business details',3).prime_sc('[prime_abn]'),'pp-card')]),'pp-mint');
        $content.=prime_section(prime_h('Google reviews').prime_p('See what customers have shared on Google.').prime_g(prime_icon_block('quote').prime_p('Verified Google reviews will appear here.').prime_p('Review placeholder — no rating or customer testimonial has been published.').prime_sc('[prime_reviews_link]'),'pp-card pp-centre'));
        $content.=prime_section(prime_cols([prime_h('Service area').prime_h('Melbourne and nearby suburbs',3).prime_p('Approved suburbs and travel information are shown before you enquire.').prime_buttons('View service areas',prime_page_link('contact'),true),prime_photo('lease','Illustrative home — service-area photography pending')]),'pp-area-feature').prime_cta();
    } elseif($key==='contact') {
        $content.=prime_section(prime_cols([prime_p('CONTACT & SERVICE AREAS','pp-eyebrow').prime_h('Let’s talk about your clean',1).prime_p('Tell us about your cleaning needs. We will help with the next step.'),prime_photo('regular','Illustrative home interior',true)],'pp-hero'),'pp-compact-hero');
        $content.=prime_section(prime_cols([prime_g(prime_h('Send an enquiry',2).prime_sc('[prime_contact_form]'),'pp-card'),prime_g(prime_h('Let’s talk',2).prime_sc('[prime_contact_details]').prime_h('A note on response times',3).prime_sc('[prime_response_notice]').prime_p('Preferred dates are requests, not confirmed bookings.','pp-small').prime_photo('carpet','Illustrative carpet cleaning'),'pp-soft-card')],'pp-two-thirds'));
        $content.=prime_section(prime_h('Our Melbourne service areas',2,'pp-centre').prime_p('Two suburb zones, with travel information shown before you enquire.','pp-centre').prime_sc('[prime_service_areas]'),'pp-mint');
        $service_cards=[];foreach(['lease'=>'key','regular'=>'sparkle','carpet'=>'brush'] as $service_key=>$icon)$service_cards[]=prime_g(prime_icon_block($icon).prime_h(prime_pages_map()[$service_key][0],3).prime_p(prime_lorem()).prime_buttons('View service',prime_page_link($service_key),true),'pp-card');
        $content.=prime_section(prime_h('Our services').prime_cols($service_cards)).prime_cta();
    } elseif($key==='blog') {
        $content.=prime_section(prime_cols([prime_p('PRIME JOURNAL','pp-eyebrow').prime_h('Notes for a fresher home',1).prime_p('Cleaning advice, home care and helpful updates.'),prime_photo('regular','Illustrative home interior',true)],'pp-hero'),'pp-compact-hero').prime_section(prime_sc('[prime_blog_listing]')).prime_cta();
    } else {
