        $sections=$key==='privacy'?['Information we collect','How information is used','Enquiries and communications','Data storage and retention','Your privacy choices','Contact us']:['Using our services','Estimates and custom quotes','Preferred dates and confirmation','Payment on completion','Cancellations','Questions about these terms'];
        $nav=prime_h('On this page',3);$body='';foreach($sections as $i=>$heading){$id='policy-'.($i+1);$nav.=prime_p('<a href="#'.$id.'">'.esc_html($heading).'</a>');$body.=prime_b('group','<section class="wp-block-group pp-legal-section" id="'.$id.'">'.prime_h(sprintf('%02d. ', $i+1).$heading).prime_p('Client-approved wording pending.').prime_p(prime_lorem()).'</section>',['tagName'=>'section','className'=>'pp-legal-section','anchor'=>$id]);}
        $content.=prime_section(prime_cols([prime_g($nav,'pp-contents'),$body],'pp-legal-layout'));
